//! 对话核心的 serde 类型: 命令入参 / 流事件。
//! (从 chat.rs 纯移动拆出, 逻辑零变化)

use serde::{Deserialize, Serialize};

// ───────────────────────── Types ─────────────────────────

#[derive(Debug, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum PermissionMode {
    Manual,
    AutoCurrent,
    AutoAll,
    Deny,
}

impl PermissionMode {
    pub(crate) fn cli_value(&self) -> &'static str {
        match self {
            PermissionMode::Manual => "default",
            PermissionMode::AutoCurrent => "acceptEdits",
            // AutoAll = 终端裸跑 claude --dangerously-skip-permissions 的同款体验:
            // 全工具免确认(headless 下 acceptEdits 只批文件编辑, 白名单外的工具
            // 一律被拒 → 与 CLI 体验割裂)。用户显式选这一档即知情放行。
            PermissionMode::AutoAll => "bypassPermissions",
            PermissionMode::Deny => "plan",
        }
    }
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ChatSendArgs {
    pub prompt: String,
    /// Explicit uploaded images; prompt paths remain available to legacy tools.
    #[serde(default)]
    pub image_paths: Option<Vec<String>>,
    /// Pi thinking level; omitted values keep the daemon's default/current level.
    #[serde(default)]
    pub thinking_level: Option<String>,
    pub permission_mode: PermissionMode,
