#!/usr/bin/env python3
"""Check physical line counts without following symlinks or scanning dependencies."""
import argparse
import json
import os
from pathlib import Path
import sys

EXCLUDED = {'.git', 'node_modules', 'vendor', '.venv', 'venv', '__pycache__',
            'dist', 'build', 'coverage', '.next', '.nuxt', 'target'}
EXTENSIONS = set(('.py .pyi .js .jsx .ts .tsx .mjs .cjs .vue .svelte .html .css '
                  '.scss .less .go .rs .java .kt .kts .swift .c .h .cc .cpp .hpp '
                  '.cs .rb .php .lua .r .sh .bash .ps1 .bat .cmd .sql .proto '
                  '.graphql .json .yaml .yml .toml').split())
LOCKFILES = {'package-lock.json', 'npm-shrinkwrap.json', 'composer.lock',
             'pnpm-lock.yaml', 'yarn.lock'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('root', type=Path)
    parser.add_argument('--files', nargs='+', help='Explicit paths relative to root')
    parser.add_argument('--limit', type=int, default=500)
    parser.add_argument('--extensions', help='Extra suffixes, comma separated')
    args = parser.parse_args()
    root = args.root.resolve()
    if not root.is_dir() or args.limit < 1:
        parser.error('root must be a directory; limit must be positive')
    extras = {part.strip().lower() for part in (args.extensions or '').split(',') if part.strip()}
    extensions = EXTENSIONS | extras
    candidates, excluded_dirs = [], []
    if args.files:
        candidates = [root / p for p in args.files]
    else:
        for folder, dirs, names in os.walk(root, followlinks=False):
            for name in list(dirs):
                path = Path(folder) / name
                if name in EXCLUDED or path.is_symlink():
                    excluded_dirs.append(str(path.relative_to(root)))
                    dirs.remove(name)
            candidates.extend(Path(folder) / name for name in names)
    report = {'limit': args.limit, 'checked': 0, 'violations': [], 'errors': [],
              'skipped': [], 'excluded_directories': excluded_dirs}
    for path in sorted(set(candidates)):
        label = str(path)
        try:
            label = str(path.relative_to(root))
            path.resolve().relative_to(root)
            if path.is_symlink():
                raise ValueError('symbolic links are not checked')
            if not path.is_file():
                raise ValueError('missing or not a regular file')
            if path.suffix.lower() not in extensions or path.name in LOCKFILES:
                report['skipped'].append(label)
                continue
            with path.open(encoding='utf-8-sig') as stream:
                lines = sum(1 for _ in stream)
            report['checked'] += 1
            if lines > args.limit:
                report['violations'].append({'path': label, 'lines': lines})
        except (OSError, UnicodeError, ValueError) as error:
            report['errors'].append({'path': label, 'error': str(error)})
    print(json.dumps(report, ensure_ascii=False, indent=2))
    if report['errors']:
        return 2
    if report['violations']:
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main())

